CREATE TABLE communities (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, retention_days INTEGER NOT NULL CHECK(retention_days BETWEEN 30 AND 3650), created_at INTEGER NOT NULL);
CREATE TABLE sources (id INTEGER PRIMARY KEY AUTOINCREMENT, community_id INTEGER NOT NULL REFERENCES communities(id), name TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, UNIQUE(community_id,name));
CREATE TABLE members (id INTEGER PRIMARY KEY AUTOINCREMENT, community_id INTEGER NOT NULL REFERENCES communities(id), external_id TEXT NOT NULL, email TEXT NOT NULL, display_name TEXT NOT NULL, digest_enabled INTEGER NOT NULL DEFAULT 0, erased_at INTEGER, created_at INTEGER NOT NULL, UNIQUE(community_id,external_id));
CREATE TABLE posts (id INTEGER PRIMARY KEY AUTOINCREMENT, source_id INTEGER NOT NULL REFERENCES sources(id), external_id TEXT NOT NULL, member_id INTEGER NOT NULL REFERENCES members(id), title TEXT NOT NULL, body TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'published' CHECK(state IN ('published','quarantined','removed')), fingerprint TEXT NOT NULL, published_at INTEGER NOT NULL, scanned_at INTEGER, created_at INTEGER NOT NULL, UNIQUE(source_id,external_id));
CREATE TABLE rules (id INTEGER PRIMARY KEY AUTOINCREMENT, community_id INTEGER NOT NULL REFERENCES communities(id), name TEXT NOT NULL, phrase TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN ('review','urgent')), enabled INTEGER NOT NULL DEFAULT 1, UNIQUE(community_id,name));
CREATE TABLE cases (id INTEGER PRIMARY KEY AUTOINCREMENT, post_id INTEGER NOT NULL REFERENCES posts(id), rule_id INTEGER NOT NULL REFERENCES rules(id), state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','dismissed','upheld')), assignee TEXT, decision_by TEXT, reason TEXT, created_at INTEGER NOT NULL, resolved_at INTEGER, UNIQUE(post_id,rule_id));
CREATE TABLE appeals (id INTEGER PRIMARY KEY AUTOINCREMENT, case_id INTEGER NOT NULL REFERENCES cases(id), reason TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'open', decision_by TEXT, resolution TEXT, created_at INTEGER NOT NULL, resolved_at INTEGER, UNIQUE(case_id));
CREATE TABLE jobs (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, payload TEXT NOT NULL, deduplication_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL DEFAULT 'ready' CHECK(state IN ('ready','leased','done','dead')), attempts INTEGER NOT NULL DEFAULT 0, available_at INTEGER NOT NULL, lease_token TEXT, lease_until INTEGER, last_error TEXT, created_at INTEGER NOT NULL, completed_at INTEGER);
CREATE TABLE erasure_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, member_id INTEGER NOT NULL REFERENCES members(id), requested_by TEXT NOT NULL, approved_by TEXT, reason TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','done','rejected')), created_at INTEGER NOT NULL, completed_at INTEGER);
CREATE TABLE deliveries (id INTEGER PRIMARY KEY AUTOINCREMENT, member_id INTEGER NOT NULL REFERENCES members(id), period TEXT NOT NULL, job_id INTEGER NOT NULL REFERENCES jobs(id), sent_at INTEGER, UNIQUE(member_id,period));
CREATE TABLE audit (id INTEGER PRIMARY KEY AUTOINCREMENT, operator TEXT NOT NULL, action TEXT NOT NULL, subject TEXT NOT NULL, details TEXT NOT NULL, occurred_at INTEGER NOT NULL);
CREATE TABLE lock_keys (key_id TEXT NOT NULL PRIMARY KEY, key_token TEXT NOT NULL, key_expiration INTEGER);
CREATE INDEX posts_retention ON posts(state,published_at);
CREATE INDEX posts_unscanned ON posts(scanned_at,id);
CREATE INDEX jobs_ready ON jobs(state,available_at,id);
CREATE INDEX jobs_leases ON jobs(state,lease_until);
CREATE INDEX cases_queue ON cases(state,created_at);
